// Tomamos el texto de la propiedad "output" del nodo anterior
const rawOutput = $input.item.json.output;

let parsedData;

try {
  // Limpiamos y convertimos el string JSON en un objeto de JavaScript real
  parsedData = JSON.parse(rawOutput);
} catch (error) {
  // Por si llega a venir plano sin formato JSON por algún motivo
  parsedData = {
    response: rawOutput,
    category: "chat sin recomendacion"
  };
}

// Devolvemos los datos limpios separados en propiedades independientes
return [{
  json: {
    response: parsedData.response,
    category: parsedData.category
  }
}];

